  Item_9819_Desc = {
    Text = "ชุด：\nไร้ตำหนิ วิวรณ์ I\nไร้ตำหนิ วิวรณ์ II\nไร้ตำหนิ วิวรณ์ III\nไร้ตำหนิ วิวรณ์ IV\nไร้ตำหนิ วิวรณ์ V\nไร้ตำหนิ วิวรณ์ VI"
